function pkpdTopic(){return level().leadGuide?.topics.find(t=>t.id==='pkpd');}
function pkpdModel(f=.6,halfLife=4){
 const ke=Math.log(2)/halfLife,ka=1.2,dt=.05,points=[];
 for(let i=0;i<=480;i++){const time=i*dt,c=f*5*ka/(ka-ke)*(Math.exp(-ke*time)-Math.exp(-ka*time));points.push([time,Math.max(0,c)]);}
 const peak=points.reduce((a,b)=>b[1]>a[1]?b:a),auc=points.slice(1).reduce((sum,p,i)=>sum+(p[1]+points[i][1])*dt/2,0);
 return {points,cmax:peak[1],tmax:peak[0],auc,halfLife};
}
function pkpdResponse(points,scenario){
 let ce=0;
 return points.map(([time,c],i)=>{
  if(scenario.ke0&&i){const dt=time-points[i-1][0],mid=(c+points[i-1][1])/2;ce=mid+(ce-mid)*Math.exp(-scenario.ke0*dt);}else if(!scenario.ke0)ce=c;
  return [time,100*ce/(scenario.ec50+ce)];
 });
}
function pkpdChart(points,{label,yLabel,max=3,color='#235f85',baseline=null,shade=false,peak=false}){
 const x=t=>58+t/24*482,y=c=>230-Math.min(c,max)/max*186;
 const path=pts=>pts.map(([t,c],i)=>(i?'L':'M')+x(t).toFixed(2)+','+y(c).toFixed(2)).join(' ');
 const ticks=[0,.25,.5,.75,1].map(f=>'<line x1="58" y1="'+y(max*f)+'" x2="540" y2="'+y(max*f)+'" stroke="#e0e8ee"/><text x="48" y="'+(y(max*f)+4)+'" text-anchor="end">'+(max*f).toFixed(max===100?0:2)+'</text>').join('');
 const xticks=[0,6,12,18,24].map(t=>'<text x="'+x(t)+'" y="250" text-anchor="middle">'+t+'</text>').join('');
 const best=points.reduce((a,b)=>b[1]>a[1]?b:a);
 const marker=peak?'<circle cx="'+x(best[0])+'" cy="'+y(best[1])+'" r="4" fill="'+color+'"/><text x="'+(x(best[0])+9)+'" y="'+(y(best[1])-10)+'" fill="'+color+'">Cmax</text>':'';
 return '<svg class="pkpd-chart" viewBox="0 0 570 280" role="img" aria-label="'+escapeHtml(label)+'"><title>'+escapeHtml(label)+'</title><rect width="570" height="280" fill="white"/><g font-family="system-ui,sans-serif" font-size="12" fill="#526579"><text x="58" y="20">'+escapeHtml(yLabel)+'</text>'+ticks+xticks+'<text x="299" y="276" text-anchor="middle">Time after a single dose (hours)</text></g>'+(shade?'<path d="'+path(points)+' L540,230 L58,230 Z" fill="'+color+'" opacity=".12"/>':'')+(baseline?'<path d="'+path(baseline)+'" fill="none" stroke="#82929b" stroke-width="2" stroke-dasharray="5 5"/>':'')+'<path d="'+path(points)+'" fill="none" stroke="'+color+'" stroke-width="3"/>'+marker+'</svg>';
}
function pkpdViewContent(t){
 const view=t.views.some(v=>v.id===state.pkpdView)?state.pkpdView:'pk';
 const pd=view==='pd',options=pd?t.pdScenarios:t.pkScenarios,selected=options.find(x=>x.id===(pd?state.pkpdResponse:state.pkpdExposure))||options[0];
 const switches='<div class="pkpd-scenarios" role="group" aria-label="'+(pd?'Compare response scenarios':'Compare exposure scenarios')+'">'+options.map(x=>'<button type="button" data-pkpd-scenario="'+x.id+'" aria-pressed="'+(selected.id===x.id)+'">'+escapeHtml(x.label)+'</button>').join('')+'</div>';
 const reference=pkpdModel(),model=pd?reference:pkpdModel(selected.f,selected.halfLife);
 let charts,metrics,footnote;
 if(pd){
  const response=pkpdResponse(model.points,selected),rapid=pkpdResponse(model.points,t.pdScenarios[0]);
  charts='<div class="pkpd-chart-pair"><figure><figcaption>Same PK in every scenario</figcaption>'+pkpdChart(model.points,{label:'Simulated unbound plasma concentration, unchanged between response scenarios',yLabel:'Unbound concentration (arbitrary units)'})+'</figure><figure><figcaption>Tumor pathway inhibition</figcaption>'+pkpdChart(response,{label:'Simulated '+selected.label+' over time',yLabel:'Modeled pathway inhibition (%)',max:100,color:'#b16824',baseline:selected.id==='immediate'?null:rapid})+'</figure></div>';
  metrics='<ol class="pkpd-readouts">'+t.readouts.map(([title,text])=>'<li><strong>'+escapeHtml(title)+'</strong><span>'+escapeHtml(text)+'</span></li>').join('')+'</ol>';
  footnote='Pathway inhibition is not tumor shrinkage. Follow tumor growth separately, and assess normal-tissue effects at the same exposures. These curves do not model tumor size or toxicity.';
 }else{
  charts='<figure class="pkpd-exposure-chart"><figcaption>Concentration–time profile</figcaption>'+pkpdChart(model.points,{label:'Simulated '+selected.label+' concentration-time curve',yLabel:'Unbound concentration (arbitrary units)',baseline:selected.id==='reference'?null:reference.points,shade:true,peak:true})+'</figure>';
  metrics='<div class="pkpd-metrics">'+[['Cmax',model.cmax.toFixed(2)+' a.u.','Peak concentration'],['Tmax',model.tmax.toFixed(1)+' h','Time of the peak'],['AUC₀–₂₄',model.auc.toFixed(1)+' a.u.·h','Exposure over 24 hours'],['Half-life',model.halfLife+' h','Terminal elimination phase']].map(([label,value,meaning])=>'<div><span>'+label+'</span><strong>'+value+'</strong><small>'+meaning+'</small></div>').join('')+'</div>';
  footnote='Same dose and distribution volume in all scenarios. Lower bioavailability can reflect limited absorption or first-pass loss; the curve alone does not identify the cause.';
 }
 const assumptions=pd?'Response = 100 × Ce / (C50 + Ce). For teaching, rapid response assumes effective tumor concentration equals unbound plasma concentration (Ce); the delayed scenario uses dCe/dt = 0.25 × (Cplasma − Ce). C50 is 0.5 arbitrary units, or 2 for lower sensitivity. These are illustrative choices, not parameters for a real drug.':'A single oral dose in a one-compartment model with first-order absorption (ka = 1.2 h⁻¹) and elimination. Dose/volume = 5 arbitrary concentration units. Bioavailability is 60% (20% in the lower-bioavailability scenario); half-life is 4 hours (1 hour with faster clearance). AUC is integrated only from 0 to 24 hours. Concentration is treated as unbound, with no changing binding or distribution.';
 return '<h4>'+(pd?'Same plasma exposure. Different tumor response.':'An oral dose is only the start of tumor delivery.')+'</h4><p class="pkpd-simulation-label">Illustrative simulation · Project Kestrel · synthetic data</p>'+switches+charts+(selected.id!==(pd?'immediate':'reference')?'<p class="pkpd-legend">Dashed gray: '+(pd?'rapid response':'reference exposure')+'. Solid '+(pd?'amber':'blue')+': selected scenario.</p>':'')+'<p class="pkpd-insight" role="status">'+escapeHtml(selected.explanation)+'</p>'+metrics+'<p class="pkpd-small">'+footnote+'</p>'+(pd?'':'<details class="lead-reference-details"><summary>PK terms and interpretation</summary>'+exampleEvidenceTable(t.reference)+'</details>')+'<details class="lead-reference-details"><summary>Model assumptions</summary><p>'+assumptions+'</p></details>'+(pd?'<button class="button primary" data-lead-topic="optimization">Apply this to lead optimization →</button>':'<button class="button primary" data-pkpd-view="pd">Next: understand the response →</button>');
}
