function leadEvidenceTopic(t,reading,controls){
 const thread=t.learningThread;
 let visual='';
 if(t.tiers)visual=leadProfilingFunnel(t);
 if(t.processCards)visual='<div class="lead-adme-map" aria-label="Four interacting ADME processes">'+t.processCards.map(c=>'<article><span class="lead-process-letter" aria-hidden="true">'+c.letter+'</span><h4>'+escapeHtml(c.title)+'</h4><strong>'+escapeHtml(c.question)+'</strong><p>'+escapeHtml(c.test)+'</p></article>').join('')+'</div>';
 if(t.flow)visual='<ol class="lead-exposure-flow" aria-label="Dose, exposure, and response">'+t.flow.map(([title,text])=>'<li><strong>'+escapeHtml(title)+'</strong><p>'+escapeHtml(text)+'</p></li>').join('')+'</ol>';
 if(t.evidenceCards)visual+='<div class="lead-evidence-cards">'+t.evidenceCards.map(c=>'<article><span>'+escapeHtml(c.tag)+'</span><h4>'+escapeHtml(c.title)+'</h4><strong>'+escapeHtml(c.value)+'</strong><p>'+escapeHtml(c.text)+'</p></article>').join('')+'</div>';
 if(t.compactProfiling){
  const guidance=t.sections.flatMap(section=>section.points).map(([title,text])=>'<li><strong>'+escapeHtml(title)+'.</strong> '+escapeHtml(text)+'</li>').join('');
  return '<div class="lead-science-topic lead-connected-topic lead-profiling-compact"><section class="stage-overview"><h3>'+escapeHtml(t.title)+'</h3><p>'+escapeHtml(t.intro)+'</p>'+visual+'<p class="lead-scope">'+escapeHtml(t.note)+'</p><details class="lead-reference-details"><summary>How to choose compounds</summary><ul>'+guidance+'</ul></details>'+reading+'<button class="button primary lead-topic-cta" data-lead-topic="'+thread.nextId+'">'+escapeHtml(thread.nextLabel)+'</button></section></div>'+controls;
 }
 const source=level().leadGuide.caseSource||level().leadGuide.vertexBranch.source;
 const caseAnchor=thread.anchorTitle?'<section class="stage-overview lead-case-anchor"><p class="eyebrow">CONNECT TO THE PUBLISHED EXAMPLE</p><h3>'+escapeHtml(thread.anchorTitle)+'</h3><div class="lead-anchor-grid"><div><h4>What the paper reports</h4><p>'+escapeHtml(thread.known)+'</p>'+indSourceLink(source)+'</div><div><h4>How to use that evidence</h4><p>'+escapeHtml(thread.questionText)+'</p></div></div><div class="lead-topic-output"><span>Leave this topic with</span><strong>'+escapeHtml(thread.output)+'</strong></div></section>':'';
 return '<div class="lead-science-topic lead-connected-topic"><section class="stage-overview"><p class="eyebrow">'+escapeHtml(thread.context||'AFTER SAR')+' · '+escapeHtml(thread.number)+' / 3</p><p class="lead-topic-bridge">'+escapeHtml(thread.previous)+' → '+escapeHtml(thread.question)+'</p><h3>'+escapeHtml(t.title)+'</h3><p>'+escapeHtml(t.intro)+'</p>'+visual+'<p class="lead-scope">'+escapeHtml(t.note)+'</p></section>'+caseAnchor+'<section class="stage-overview lead-topic-reference">'+(t.table?'<details class="lead-reference-details"><summary>'+escapeHtml(t.table.title)+' · reference</summary>'+exampleEvidenceTable(t.table)+'</details>':'')+((t.workedExample||t.sections?.length)?'<details class="lead-reference-details'+(t.workedExample?' adme-principles':'')+'"'+(t.workedExample?' open':'')+'><summary>'+escapeHtml(t.principlesTitle||'Explore the supporting principles')+'</summary>'+(t.workedExample?admeWorkedExample(t.workedExample):'')+leadPrinciples(t.sections)+'</details>':'')+'<div class="takeaway"><span>Keep this idea</span><strong>'+escapeHtml(t.keep)+'</strong></div><button class="button primary lead-topic-cta" data-lead-topic="'+thread.nextId+'">'+escapeHtml(thread.nextLabel)+'</button>'+reading+'</section></div>'+controls;
}

