function hitProgramContent(){
 const e=hitProgram(),stages=e.stages,current=stages.find(s=>s.id===state.hitStage)||stages[0];
 if(e.decisionMap)return vertexProgramMap();
 const navigation=e.branchMap?'<div class="hit-stage-nav vertex-branch-nav" role="group" aria-label="Two SAR branches from hit 1 and the resulting lead">'+stages.map(s=>{const branch=e.branchMap.find(b=>b.stage===s.id);return '<button data-hit-stage="'+s.id+'" aria-pressed="'+(s.id===current.id)+'" aria-controls="hit-example-panel"'+(!branch?' class="vertex-route-lead"':'')+'><strong>'+escapeHtml(branch?branch.label:s.label)+'</strong><small>'+escapeHtml(branch?branch.text:'The lead identified from amine exploration.')+'</small></button>';}).join('')+'</div>':'<div class="hit-stage-nav" role="group" aria-label="Published example stages">'+stages.map((s,i)=>'<button data-hit-stage="'+s.id+'" aria-pressed="'+(s.id===current.id)+'" aria-controls="hit-example-panel"><span>'+(i+1)+'</span> '+escapeHtml(s.label)+'</button>').join('')+'</div>';
 return '<div class="hit-program-intro"><h3>'+escapeHtml(e.title)+'</h3><p>'+escapeHtml(e.intro)+'</p><p class="hit-program-note">'+escapeHtml(e.note)+'</p></div>'+navigation+'<section id="hit-example-panel" aria-live="polite">'+hitStageContent(current)+'</section>';
}
function hitStageControls(stages,i){
 return '<div class="hit-stage-controls">'+(i?'<button class="text-button" data-hit-stage="'+stages[i-1].id+'">← Previous stage</button>':'<span></span>')+'<span>'+(i+1)+' / '+stages.length+'</span>'+(i<stages.length-1?'<button class="text-button" data-hit-stage="'+stages[i+1].id+'">Next stage →</button>':'<span>Continue with “Your turn” below ↓</span>')+'</div>';
}

function hitStageContent(s){
 const e=hitProgram(),i=e.stages.findIndex(x=>x.id===s.id),hasFigures=Boolean(s.figures?.length),hasEvidence=hasFigures||Boolean(s.table);
 if(s.decisions)return vertexOptimizationView(s)+hitStageControls(e.stages,i);
 if(s.compoundGrid){
  const g=level().leadGuide.vertexBranch;
  return '<section class="stage-overview vertex-example-grid"><h3>'+escapeHtml(s.title)+'</h3><p>'+escapeHtml(s.observation)+'</p><p class="vertex-legend"><span aria-hidden="true"></span>Amber highlights atoms and bonds added relative to reference compound 7.</p><div class="vertex-branch-diagram">'+vertexMoleculeCards(g.compounds)+'</div><p class="vertex-assay">EC<sub>50</sub> ± SD in the NIH-3T3 F508del-CFTR potentiation assay, from at least three determinations. Lower values indicate greater potency.</p><div class="hit-interpretation"><p><strong>Supports</strong> '+escapeHtml(s.meaning)+'</p><p><strong>Limit</strong> '+escapeHtml(s.limit)+'</p></div><div class="hit-source">'+(s.sources||e.sources).map(indSourceLink).join('')+'</div></section>'+hitStageControls(e.stages,i);
 }
 const interpretation='<div class="hit-interpretation"><p><strong>Supports</strong> '+escapeHtml(s.meaning)+'</p><p><strong>Limit</strong> '+escapeHtml(s.limit)+'</p></div>';
 const right=s.table?'<section class="target-case hit-table-card"><p class="eyebrow">READ THE EVIDENCE</p><h3>'+escapeHtml(s.table.title)+'</h3>'+exampleEvidenceTable(s.table)+'</section>':hasFigures?'<section class="target-case hit-figure-card" aria-label="Stage illustration and evidence"><p class="eyebrow">'+escapeHtml(s.figureHeading||'FROM THE PAPER')+'</p><div class="hit-figure-gallery">'+s.figures.map(f=>'<figure class="'+(f.layout==='wide'?'hit-paper-wide':f.layout==='compact'?'hit-paper-compact':f.layout==='portrait'?'hit-paper-portrait':f.layout==='lead'?'hit-paper-lead':'')+'"><h4>'+escapeHtml(f.label)+'</h4><a class="hit-figure-link" href="'+escapeHtml(f.src)+'" target="_blank" rel="noopener noreferrer" aria-label="Open '+escapeHtml(f.label)+' at full size in a new tab"><img src="'+escapeHtml(f.src)+'" alt="'+escapeHtml(f.alt)+'" width="'+f.width+'" height="'+f.height+'"></a><figcaption>'+escapeHtml(f.caption)+' <a href="'+escapeHtml(f.src)+'" target="_blank" rel="noopener noreferrer">Enlarge panel ↗</a></figcaption></figure>').join('')+'</div><p class="hit-figure-credit">'+escapeHtml(s.figureCredit||e.figureCredit)+'</p></section>':'<section class="target-case"><p class="eyebrow">READ THE EVIDENCE</p><h3>What this supports</h3><p>'+escapeHtml(s.meaning)+'</p><div class="hit-limit"><h4>What it does not establish</h4><p>'+escapeHtml(s.limit)+'</p></div></section>';
 return '<div class="target-layout hit-example-layout'+(hasEvidence?' has-figures':'')+'"><section class="target-principles"><p class="eyebrow">PUBLISHED EXPERIMENT · '+(i+1)+' / '+e.stages.length+'</p><h3>'+escapeHtml(s.title)+'</h3><p>'+escapeHtml(s.observation)+'</p>'+(s.reading?'<dl class="hit-reading-notes">'+s.reading.map(([title,text])=>'<div><dt>'+escapeHtml(title)+'</dt><dd>'+escapeHtml(text)+'</dd></div>').join('')+'</dl>':'')+(s.hideSummaryDiagram?'':'<div class="hit-evidence-flow">'+s.diagram.map(([label,detail])=>'<div><small>'+escapeHtml(label)+'</small><strong>'+escapeHtml(detail)+'</strong></div>').join('')+'</div>')+(hasEvidence?interpretation:'')+'<div class="hit-source">'+(s.sources||e.sources).map(indSourceLink).join('')+'</div></section>'+right+'</div>'+hitStageControls(e.stages,i);
}

const VERTEX_EXAMPLE_TABS=[['baseline','Profile lead 16'],['core','Explore the amide linker'],['rings','Explore the indole ring'],['substitutions','Substitute the indole'],['ringopen','Open the ring'],['phenol','Build the phenol series'],['compare','Both branches meet'],['confirm','Lead 16 → DC 48']];
function vertexCurrentExampleTab(){if(state.vertexExampleTab==='branches')return 'compare';return VERTEX_EXAMPLE_TABS.some(([id])=>id===state.vertexExampleTab)?state.vertexExampleTab:'baseline';}
function vertexProgramMap(){
 const tab=vertexCurrentExampleTab(),nodes=hitProgram().decisionMap.nodes;
 const allowed={baseline:['baseline'],rings:['rings'],core:['core'],substitutions:['branches'],ringopen:['ringopen'],phenol:['phenol'],branches:['branches','ringopen','phenol','baseline','rings','core','compare','confirm','advance'],compare:['compare'],confirm:['confirm','advance']};
 const id=allowed[tab].includes(state.vertexMapNode)?state.vertexMapNode:tab==='substitutions'?'branches':tab;
 const n=nodes.find(n=>n.id===id);
 const nav='<div class="vertex-example-tabs" role="tablist" aria-label="Vertex lead optimization example">'+VERTEX_EXAMPLE_TABS.map(([id,label],i)=>'<button type="button" role="tab" id="vertex-tab-'+id+'" aria-selected="'+(id===tab)+'" tabindex="'+(id===tab?'0':'-1')+'" aria-controls="vertex-example-tabpanel" data-vertex-example-tab="'+id+'"><span>'+(i+1)+'</span>'+label+'</button>').join('')+'</div>';
 const content=tab==='branches'?vertexProgramTree():tab==='baseline'?vertexLeadProfileTab(n):tab==='rings'?vertexIndoleTab(n):tab==='core'?vertexLinkerTab(n):tab==='substitutions'?vertexIndoleSubstitutionTab(n):tab==='ringopen'?vertexRingOpenTab(n):tab==='phenol'?vertexPhenolTab(n):tab==='compare'?vertexBranchesMeet():tab==='confirm'?vertexLeadToDC():vertexProgramMapDetail(n);
 const i=VERTEX_EXAMPLE_TABS.findIndex(([id])=>id===tab);
 const footer='<div class="vertex-example-tab-controls">'+(i?'<button type="button" class="text-button" data-vertex-example-tab="'+VERTEX_EXAMPLE_TABS[i-1][0]+'">← '+VERTEX_EXAMPLE_TABS[i-1][1]+'</button>':'<span></span>')+(i<VERTEX_EXAMPLE_TABS.length-1?'<button type="button" class="button primary" data-vertex-example-tab="'+VERTEX_EXAMPLE_TABS[i+1][0]+'">Next: '+VERTEX_EXAMPLE_TABS[i+1][1]+' →</button>':'<span class="vertex-example-end">End of the published example</span>')+'</div>';
 return vertexOverviewDiagram()+nav+'<section id="vertex-example-tabpanel" role="tabpanel" aria-labelledby="vertex-tab-'+tab+'">'+(tab==='branches'?content:'<section id="hit-example-panel" aria-live="polite">'+content+'</section>')+'</section>'+footer;
}
