 state.hitStage=id;$('#hit-example-panel').innerHTML=hitStageContent(selected);
 document.querySelectorAll('.hit-stage-nav [data-hit-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.hitStage===id)));
 const active=$('.hit-stage-nav [data-hit-stage="'+id+'"]');if(active)active.focus({preventScroll:true});
