function targetUnderstanding(){
 const l=level(),g=l.targetGuide;
 return `<p class="eyebrow">THE CONCEPT</p><h2>${escapeHtml(l.title)}</h2><p class="target-objective">Define what to change, how to change it, and what evidence would justify the intervention.</p><div class="target-layout"><section class="target-principles" aria-labelledby="target-principles-title"><p class="eyebrow">UNDERSTAND THE PRINCIPLE</p><h3 id="target-principles-title">Start with what is known</h3><p>${escapeHtml(l.concept)}</p><h3>Validate the therapeutic hypothesis</h3><p>${escapeHtml(g.validation)}</p><div class="target-causality"><span class="eyebrow">FROM HYPOTHESIS TO EVIDENCE</span>${conceptDiagram()}</div><p class="target-perturbation">${escapeHtml(g.perturbationNote)}</p><div class="takeaway"><span>Keep this idea</span><strong>${escapeHtml(l.takeaway)}</strong></div></section><section class="target-case" aria-labelledby="target-case-title"><p class="eyebrow">DEFINE YOUR STRATEGY</p><h3 id="target-case-title">${escapeHtml(g.caseTitle)}</h3><p class="target-case-intro">${escapeHtml(g.caseIntro)}</p>${targetLayers(g.layers,'What to specify')}<div class="target-validation"><h4>What would you need to validate?</h4><ul>${g.questions.map(q=>`<li>${escapeHtml(q)}</li>`).join('')}</ul></div></section></div>`;
}
function targetLayers(layers,column){return `<table class="target-layers"><caption class="sr-only">Target, therapeutic hypothesis, and binding strategy</caption><thead><tr><th scope="col">Decision</th><th scope="col">${escapeHtml(column)}</th></tr></thead><tbody>${layers.map(row=>`<tr><th scope="row">${escapeHtml(row.label)}<small>${escapeHtml(row.question)}</small></th><td>${escapeHtml(row.example)}</td></tr>`).join('')}</tbody></table>`;}
const PI3K_CATEGORIES=[['rationale','Biological rationale'],['timeline','Discovery & clinical timeline'],['allosteric','Allosteric inhibitors']];
function pi3kExampleView(){
 const current=PI3K_CATEGORIES.some(c=>c[0]===state.pi3kCategory)?state.pi3kCategory:'rationale';
 return `<div class="pi3k-categories" role="group" aria-label="PI3K example categories">${PI3K_CATEGORIES.map(([id,label])=>`<button data-pi3k-category="${id}" aria-pressed="${id===current}" aria-controls="pi3k-panel">${escapeHtml(label)}</button>`).join('')}</div><section id="pi3k-panel" class="pi3k-panel" aria-live="polite">${pi3kCategoryContent(current)}</section>`;
}
function pi3kCategoryContent(category){
 const e=level().pi3kExample;
 if(category==='timeline'){
  const milestones=e.milestones.filter(m=>m.id!=='allosteric-2023'),current=milestones.find(m=>m.id===state.pi3kMilestone)||milestones[0];
  return `<h3>How the evidence accumulated</h3><p class="fine-print">${escapeHtml(e.scope)} PFS means progression-free survival; OS means overall survival. A hazard ratio below 1 favors the investigational arm for the specified endpoint.</p><div class="pi3k-timeline"><nav aria-label="PI3K milestones"><ol>${milestones.map(m=>`<li><button data-pi3k-milestone="${m.id}" aria-pressed="${m.id===current.id}" aria-controls="pi3k-milestone-detail"><span>${escapeHtml(m.year)}</span>${escapeHtml(m.label)}</button></li>`).join('')}</ol></nav><article id="pi3k-milestone-detail" class="pi3k-milestone" tabindex="-1">${pi3kMilestoneDetail(current,milestones)}</article></div>`;
 }
 if(category==='allosteric'){
  const d=e.distinction,m=e.milestones.find(x=>x.id==='allosteric-2023');
  return `<h3>Allosteric inhibitors: addressing toxicity and resistance</h3><p>${escapeHtml(d.intro)}</p><div class="pi3k-allosteric"><section class="pi3k-strategy-card"><h4>Why change the binding strategy?</h4><div class="pi3k-strategy-goals"><p>${escapeHtml(e.allostericRationale.toxicity)}</p><p>${escapeHtml(e.allostericRationale.resistance)}</p></div><h4>Define the strategy</h4>${targetLayers(d.layers,'PI3Kα example')}<p>${escapeHtml(d.discovery)}</p><div class="target-validation"><h4>Three questions for validation</h4><ul>${d.questions.map(q=>`<li>${escapeHtml(q)}</li>`).join('')}</ul></div></section><section class="pi3k-evidence-card"><div class="pi3k-compound-intro"><div class="pi3k-compound-copy"><h4 class="pi3k-compound-title">RLY-2608 and STX-478</h4><p>${escapeHtml(m.evidence)}</p></div><div class="pi3k-structure-frame"><img class="pi3k-structure-image" src="assets/pi3k-protein-structure.png" alt="Protein ribbon structure with highlighted bound molecules" width="404" height="495"></div></div><p class="pi3k-limit"><strong>What remains open</strong> ${escapeHtml(m.limit)}</p><h4>Read the discovery studies</h4><ul class="pi3k-reading">${m.sources.slice(0,2).map(s=>`<li>${indSourceLink(s)}</li>`).join('')}</ul><h4>Mechanism and resistance</h4><ul class="pi3k-reading">${e.allostericRationale.sources.map(s=>`<li>${indSourceLink(s)}</li>`).join('')}</ul><h4>Follow clinical translation</h4><p class="fine-print">These study records describe clinical investigation; they are not proof of marketing approval.</p><ul class="pi3k-reading">${m.sources.slice(2).map(s=>`<li>${indSourceLink(s)}</li>`).join('')}</ul></section></div>`;
 }
 return `<h3>Why inhibit PI3K?</h3><p>${escapeHtml(e.rationale)}</p>${boxes([['Disease mechanism','Mutant signaling can support tumor growth'],['Intervention','Reduce disease-driving PI3Kα activity'],['Therapeutic window','Seek tumor benefit while preserving normal function']])}${pi3kRationaleTimeline()}<div class="pi3k-rationale-notes"><section><h4>A family, not one interchangeable target</h4><p>The timeline includes PI3Kδ inhibition in blood cancers and PI3Kα inhibition in solid tumors. Evidence for one isoform and disease does not automatically validate another.</p></section><section><h4>Why this is a target-validation story</h4><p>Each stage closes a different gap: identify the activity, connect it to cancer, test causality, develop a usable inhibitor, and evaluate patient benefit.</p></section></div><div class="worked-answer"><span>How to reason through it</span><p>${escapeHtml(level().worked)}</p></div>${pi3kToxicityBridge()}`;
}
function pi3kRationaleTimeline(){
 const selected=[['activity-1985','A biochemical clue','Activity associated with transformation'],['mutations-2004','Human cancer genetics','Recurrent PIK3CA mutations'],['function-2005','Functional validation','Mutants drive transformation in a model'],['idelalisib-2014','PI3Kδ in blood cancer','Idelalisib: clinical benefit in CLL'],['solar-2019','PI3Kα in breast cancer','SOLAR-1: mutation-selected treatment'],['inavo-2024','Refine the regimen','INAVO120: test a PI3Kα-based triplet']];
 return `<section class="pi3k-summary-timeline" aria-labelledby="pi3k-summary-title"><div class="pi3k-summary-heading"><h4 id="pi3k-summary-title">From a biological clue to clinical evidence</h4><button class="button quiet" data-pi3k-category="timeline">Explore the timeline →</button></div><p class="fine-print">Selected milestones in target discovery, validation, and clinical development.</p><div class="pi3k-summary-scroll" role="region" aria-label="Horizontal PI3K milestone timeline" tabindex="0"><ol>${selected.map(([id,title,description])=>{const m=level().pi3kExample.milestones.find(x=>x.id===id);return `<li><div class="pi3k-summary-item"><span class="pi3k-summary-year">${escapeHtml(m.year)}</span><span class="pi3k-summary-dot" aria-hidden="true"></span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(description)}</small></div></li>`;}).join('')}</ol></div></section>`;
}
function pi3kToxicityBridge(){
 const t=level().pi3kExample.toxicity;
 return `<section class="pi3k-toxicity" aria-labelledby="pi3k-toxicity-title"><div class="pi3k-summary-heading"><h4 id="pi3k-toxicity-title">${escapeHtml(t.title)}</h4><button class="button primary" data-pi3k-category="allosteric">Explore allosteric inhibitors →</button></div><p>${escapeHtml(t.mechanism)}</p><p>${escapeHtml(t.clinical)}</p><div class="ind-source-links">${t.sources.map(indSourceLink).join('')}</div></section>`;
}
function pi3kMilestoneDetail(m,milestones){
 const i=milestones.indexOf(m);
 return `<p class="eyebrow">${escapeHtml(m.year)} · ${escapeHtml(m.kind)}</p><h4>${escapeHtml(m.title)}</h4>${m.trial?`<p class="pi3k-trial">${escapeHtml(m.trial)}</p>`:''}<p>${escapeHtml(m.evidence)}</p><div class="pi3k-learning"><strong>What this added</strong><p>${escapeHtml(m.meaning)}</p></div><p class="pi3k-limit"><strong>What it did not establish</strong> ${escapeHtml(m.limit)}</p><ul class="pi3k-reading">${m.sources.map(s=>`<li>${indSourceLink(s)}</li>`).join('')}</ul><div class="pi3k-timeline-controls">${i?`<button class="text-button" data-pi3k-milestone="${milestones[i-1].id}">← Previous milestone</button>`:'<span></span>'}<span>${i+1} / ${milestones.length}</span>${i<milestones.length-1?`<button class="text-button" data-pi3k-milestone="${milestones[i+1].id}">Next milestone →</button>`:`<button class="text-button" data-pi3k-category="allosteric">Allosteric inhibitors →</button>`}</div>`;
}
function selectPi3kCategory(id){
 if(state.screen!=='lesson'||state.step!==1||!level().pi3kExample||!PI3K_CATEGORIES.some(c=>c[0]===id))return;
 state.pi3kCategory=id;$('#pi3k-panel').innerHTML=pi3kCategoryContent(id);
 document.querySelectorAll('.pi3k-categories [data-pi3k-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pi3kCategory===id)));
 const active=$('.pi3k-categories [data-pi3k-category="'+id+'"]');if(active)active.focus({preventScroll:true});
}
