document.addEventListener('keydown',event=>{
 const tab=event.target.closest('.vertex-example-tabs [role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
 const i=VERTEX_EXAMPLE_TABS.findIndex(([id])=>id===tab.dataset.vertexExampleTab);if(i<0)return;
 event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?VERTEX_EXAMPLE_TABS.length-1:(i+(event.key==='ArrowRight'?1:-1)+VERTEX_EXAMPLE_TABS.length)%VERTEX_EXAMPLE_TABS.length;
 selectVertexExampleTab(VERTEX_EXAMPLE_TABS[next][0]);
});
